-- ═══ IL COSTO E LA DATA VERI DEGLI USATI STORICI ══════════════════════════
-- Rilievo della revisione del 02/09, e sono due difetti che si tenevano per
-- mano.
--
-- ⚠️ 1. IL COSTO NON C'ERA. Misurato: 221 telefoni su 281 hanno
-- `purchase_price = 0` — e tutti e 35 i venduti. Zero non vuol dire «regalato»,
-- vuol dire «non registrato»: sono arrivati dal vecchio gestionale senza il
-- prezzo. La regola dei 100 € — «sotto i cento, nel file va cento» — li
-- trattava come acquisti da zero euro e li portava tutti a 100: nel resoconto
-- di agosto sarebbero usciti 27.561 € di costo INVENTATO da un `max()`, e
-- quella cifra sarebbe finita nel corpo dell'email come importo da fatturare
-- fra le due società.
-- Il costo vero ce l'aveva il file «Recap Storico Usati»: 200 telefoni su 207,
-- 24.482 € in tutto.
--
-- ⚠️ 2. E LA DATA D'ACQUISTO ERA QUELLA DELL'IMPORT. La migrazione di prima
-- scriveva `coalesce(purchase_date, s.dta)` credendo che il campo fosse vuoto:
-- non lo era mai — portava il timestamp del caricamento nel CRM. Risultato:
-- 278 telefoni su 281 risultano «comprati in agosto 2026», compresi quelli del
-- 2024. Il foglio «Comprati» del mese sarebbe stato l'intero archivio storico
-- presentato come acquisti del mese.
-- Qui la data del documento vince, perché è quella che il commercialista
-- cerca. Le date vere vanno dal 2024 (5 telefoni) al 2026 (162).

create temp table _fix (imei text, costo numeric, dta date) on commit drop;

update public.usati u
   set purchase_price = coalesce(f.costo, u.purchase_price),
       /* ⚠️ QUI SI SOVRASCRIVE, ed è voluto: la data che c'era è il momento in
          cui il telefono è entrato nel CRM, non quando l'abbiamo comprato. */
       purchase_date  = coalesce(f.dta::timestamptz, u.purchase_date)
  from _fix f
 where u.imei = f.imei;

do $$
declare zero int; conCosto int; ago int; tot numeric;
begin
    select count(*) filter (where purchase_price = 0 or purchase_price is null),
           count(*) filter (where purchase_price > 0),
           count(*) filter (where purchase_date >= '2026-08-01' and purchase_date < '2026-09-01'),
           coalesce(sum(purchase_price), 0)
      into zero, conCosto, ago, tot from public.usati;
    raise notice 'costo a zero: % - con costo: % - datati agosto 2026: % - costo totale: % euro', zero, conCosto, ago, round(tot);
    if conCosto = 0 then raise exception 'nessun costo scritto'; end if;
end $$;
